-- RFN USA Bikes + Separate Parts Per Bike
-- Run this entire file once in Supabase SQL Editor.
create extension if not exists pgcrypto;

create or replace function public.set_updated_at()
returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end; $$;

create table if not exists public.bikes (
 id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique,
 quantity integer not null default 0 check(quantity>=0),
 status text not null default 'in_stock' check(status in('in_stock','pre_order','out_of_stock','hidden')),
 dealer_price numeric(12,2) not null default 0, retail_price numeric(12,2) not null default 0,
 image_url text, catalog_url text, colors text[] not null default '{}', featured boolean not null default true,
 description text, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);

drop trigger if exists bikes_set_updated_at on public.bikes;
create trigger bikes_set_updated_at before update on public.bikes for each row execute function public.set_updated_at();

-- Ensure existing bikes table has every required column.
alter table public.bikes add column if not exists name text;
alter table public.bikes add column if not exists slug text;
alter table public.bikes add column if not exists quantity integer default 0;
alter table public.bikes add column if not exists status text default 'in_stock';
alter table public.bikes add column if not exists dealer_price numeric(12,2) default 0;
alter table public.bikes add column if not exists retail_price numeric(12,2) default 0;
alter table public.bikes add column if not exists image_url text;
alter table public.bikes add column if not exists catalog_url text;
alter table public.bikes add column if not exists colors text[] default '{}';
alter table public.bikes add column if not exists featured boolean default true;
alter table public.bikes add column if not exists description text;
alter table public.bikes add column if not exists created_at timestamptz default now();
alter table public.bikes add column if not exists updated_at timestamptz default now();
create unique index if not exists bikes_slug_unique on public.bikes(slug) where slug is not null;

create table if not exists public.inventory (
 id uuid primary key default gen_random_uuid(),
 bike_id uuid references public.bikes(id) on delete cascade,
 bike_model text not null default '', part_name text not null, part_number text not null,
 quantity integer not null default 3 check(quantity>=0), dealer_price numeric(12,2) not null default 0,
 retail_price numeric(12,2) not null default 0, location text, notes text,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);

alter table public.inventory add column if not exists bike_id uuid references public.bikes(id) on delete cascade;
alter table public.inventory add column if not exists bike_model text default '';
alter table public.inventory add column if not exists part_name text;
alter table public.inventory add column if not exists part_number text;
alter table public.inventory add column if not exists quantity integer default 3;
alter table public.inventory add column if not exists dealer_price numeric(12,2) default 0;
alter table public.inventory add column if not exists retail_price numeric(12,2) default 0;
alter table public.inventory add column if not exists location text;
alter table public.inventory add column if not exists notes text;
alter table public.inventory add column if not exists created_at timestamptz default now();
alter table public.inventory add column if not exists updated_at timestamptz default now();
update public.inventory set quantity=3 where quantity is null;
update public.inventory set part_number='LEGACY-'||id::text where part_number is null or trim(part_number)='';
alter table public.inventory alter column quantity set default 3;
alter table public.inventory alter column part_number set not null;

drop trigger if exists inventory_set_updated_at on public.inventory;
create trigger inventory_set_updated_at before update on public.inventory for each row execute function public.set_updated_at();

-- A part number is unique only inside one bike. The same number may exist on another bike.
drop index if exists inventory_part_number_key;
drop index if exists inventory_part_number_idx;
-- Remove duplicate rows only when the same bike and same part number already exist.
with ranked as (select id,row_number() over(partition by bike_id,upper(trim(part_number)) order by updated_at desc nulls last,created_at desc nulls last,id) rn from public.inventory where bike_id is not null) delete from public.inventory i using ranked r where i.id=r.id and r.rn>1;
create unique index if not exists inventory_bike_part_unique
on public.inventory(bike_id, upper(trim(part_number))) where bike_id is not null;

-- This restored admin version allows any authenticated account to manage bikes and inventory.
alter table public.bikes enable row level security;
alter table public.inventory enable row level security;
drop policy if exists "Authenticated manage bikes" on public.bikes;
create policy "Authenticated manage bikes" on public.bikes for all to authenticated using(true) with check(true);
drop policy if exists "Public read bikes" on public.bikes;
create policy "Public read bikes" on public.bikes for select to anon using(status<>'hidden');
drop policy if exists "Authenticated manage inventory" on public.inventory;
create policy "Authenticated manage inventory" on public.inventory for all to authenticated using(true) with check(true);
drop policy if exists "Authenticated read inventory" on public.inventory;
create policy "Authenticated read inventory" on public.inventory for select to authenticated using(true);
grant select on public.bikes to anon,authenticated;
grant insert,update,delete on public.bikes to authenticated;
grant select,insert,update,delete on public.inventory to authenticated;


-- Assign old inventory rows to matching bikes where possible.
update public.inventory i set bike_id=b.id from public.bikes b where i.bike_id is null and lower(trim(i.bike_model)) in (lower(trim(b.name)),lower(trim(b.slug)));


select b.name,count(i.id) as parts,coalesce(sum(i.quantity),0) as total_units from public.bikes b left join public.inventory i on i.bike_id=b.id group by b.id,b.name order by b.name;
